import {STATUS,ACTIVE,total,paid,balance,paymentStatus,normalizeWA,canTransition,recap,validatePayment,csvCell} from './core.js';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'Rp'+Number(v||0).toLocaleString('id-ID');
const dateISO=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
const today=dateISO();
const addDay=(n,base=today)=>{const d=new Date(base+'T12:00:00+07:00');d.setDate(d.getDate()+n);return dateISO(d)};
const dateLabel=(date,short=false)=>new Intl.DateTimeFormat('id-ID',{day:'numeric',month:short?'short':'long',...(!short?{year:'numeric'}:{}),timeZone:'Asia/Jakarta'}).format(new Date(date+'T12:00:00+07:00'));
const timeLabel=v=>new Intl.DateTimeFormat('id-ID',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(v));
const uid=()=>crypto.randomUUID();
const paths={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',orders:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 9h6M9 13h6M9 17h3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',box:'<path d="m3 7 9-4 9 4-9 4zM3 7v10l9 4 9-4V7M12 11v10M7 5l9 4"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',card:'<rect x="2" y="4" width="20" height="16" rx="3"/><path d="M2 10h20M6 15h4"/>',store:'<path d="m3 8 2-5h14l2 5M3 8v3a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0V8M5 14v7h14v-7M9 21v-5h6v5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M20 8V5H5a3 3 0 0 0 0 6h16v9H5a3 3 0 0 1-3-3V8M21 12h-5v5h5"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6zM13 6l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M5 17v4h14v-4"/>',link:'<path d="m10 13 4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M13 7l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',design:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 10h18M10 10v11"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',logout:'<path d="M9 4H4v16h5M10 12h11m-4-4 4 4-4 4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.box}</svg>`;
const brand=()=>`<a class="brand" href="#ringkasan"><span class="brand-mark">P</span>PesanKue<span style="color:var(--accent)">.</span></a>`;
function seed(){const products=[{id:'p1',name:'Brownies Panggang',description:'Cokelat pekat, bagian tengah lembut, dengan lapisan atas yang renyah.',photo:'brownies',active:true,variants:[{name:'Original',price:45000},{name:'Keju',price:55000}]},{id:'p2',name:'Strawberry Cake',description:'Kue vanila lembut dengan krim ringan dan stroberi segar.',photo:'cake',active:true,variants:[{name:'Diameter 16 cm',price:185000},{name:'Diameter 20 cm',price:245000}]},{id:'p3',name:'Choco Chip Cookies',description:'Cookies dengan pinggiran renyah dan potongan cokelat melimpah.',photo:'cookies',active:true,variants:[{name:'Box 6 pcs',price:60000},{name:'Box 12 pcs',price:110000}]}];
const make=(i,name,day,status,prod,qty,payment,time,source='Link toko')=>{const pp=products[prod];return {id:'PK-'+(1041+i),token:uid(),name,wa:'628000000000',date:addDay(day),time,method:i%2?'Dikirim':'Ambil sendiri',address:i%2?'Alamat contoh, Bandung':'',source,status,shipping:i%2?15000:0,dpPercent:50,items:[{pid:pp.id,name:pp.name,variant:pp.variants[0].name,price:pp.variants[0].price,qty,note:i===1?'Tulisan: Selamat ulang tahun, Ayu!':''}],payments:payment?[{id:uid(),amount:payment,type:'payment',method:'Transfer',date:today,note:'Pembayaran contoh'}]:[],events:[{label:'Pesanan diterima melalui '+source,at:new Date().toISOString()}],createdAt:new Date().toISOString()}};
return {version:1,shop:{name:'Dapur Nara',owner:'Nara',wa:'628000000000',address:'Jl. Melati No. 12, Bandung (alamat contoh)',bank:'Bank Contoh',account:'0000000000',holder:'Nara — data contoh',dp:50,pickup:true,delivery:true,timezone:'Asia/Jakarta'},subscription:{status:'trial',end:addDay(5),invoice:null},products,orders:[make(0,'Alya Putri',1,'pending',0,3,0,'10:00'),make(1,'Rina Pratiwi',1,'pending',1,1,0,'15:00'),make(2,'Dewi Anggraini',0,'processing',0,4,90000,'11:00'),make(3,'Maya Sari',0,'ready',2,2,135000,'14:00'),make(4,'Sinta Maharani',0,'confirmed',1,1,100000,'16:30'),make(5,'Fitri Wulandari',2,'confirmed',2,4,120000,'09:00'),make(6,'Tania Putri',-1,'done',0,2,90000,'10:00'),make(7,'Bunga Lestari',3,'pending',0,5,0,'13:00')],lastToken:null};}
let state;try{state=JSON.parse(localStorage.getItem('pesankue-demo-v1'))}catch{}if(!state||state.version!==1)state=seed();
let cart=[],calendarDate=today,calendarMonth=today.slice(0,7),filters={search:'',status:'all',payment:'all'},productSearch='',route='',draftItems=[],onboardingStep=1,setupDraft={},toastTimer,returnFocus=null;
function persist(){try{localStorage.setItem('pesankue-demo-v1',JSON.stringify(state));return true}catch{toast('Penyimpanan browser penuh. Perubahan hanya tersedia selama halaman ini terbuka.');return false}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function openModal(title,body,small=false){const m=$('#modal');returnFocus=document.activeElement;m.className=small?'small-dialog':'';m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="btn secondary icon-only" data-action="close" aria-label="Tutup">${icon('close')}</button></div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal()}
function closeModal(){const m=$('#modal');if(m.open)m.close();if(returnFocus?.isConnected)returnFocus.focus()}
const field=(label,name,value='',type='text',extra='')=>`<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const btn=(text,action,cls='',id='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${text}</button>`;
const badge=o=>`<span class="badge ${o.status}">${STATUS[o.status]}</span>`;
const payBadge=o=>`<span class="badge ${paymentStatus(o)}">${{unpaid:'Belum dibayar',partial:'Dibayar sebagian',paid:'Lunas'}[paymentStatus(o)]}</span>`;
const isExpired=()=>state.subscription.status==='expired'||state.subscription.end<today;
const empty=(title,sub='')=>`<div class="empty">${icon('orders')}<h3>${title}</h3><p class="small">${sub}</p></div>`;
const heading=(title,sub,action='')=>`<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
const addOrderBtn=()=>btn(icon('plus')+'Tambah pesanan','new-order');
function orderRows(orders){return orders.length?orders.map(o=>`<button class="order-row" data-action="detail" data-id="${o.id}"><span class="avatar">${esc(o.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div><div class="name">${esc(o.name)}</div><div class="meta">${o.id} · ${o.items.reduce((s,x)=>s+x.qty,0)} produk</div><div class="meta">${dateLabel(o.date,true)} · ${o.time} WIB</div></div><div class="row-right"><span class="money">${money(total(o))}</span>${badge(o)}${route==='pesanan'?payBadge(o):''}</div></button>`).join(''):empty('Belum ada pesanan','Pesanan yang sesuai akan tampil di sini.')}
function navLink(key,label,ic){return `<a href="#${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`}
function shell(body){return `<aside class="sidebar">${brand()}<a href="#pengaturan" class="shop-switch"><span class="avatar">DN</span><div><strong class="small">${esc(state.shop.name)}</strong><small>Toko kamu</small></div></a><p class="nav-label">RUANG KERJA</p><nav class="nav" aria-label="Menu utama">${navLink('ringkasan','Ringkasan','home')}${navLink('pesanan','Pesanan','orders')}${navLink('kalender','Kalender','calendar')}${navLink('produk','Produk','box')}</nav><div class="sidebar-bottom"><div class="trial-card"><span class="badge pending">${isExpired()?'Masa aktif habis':state.subscription.status==='trial'?'Uji coba gratis':'Paket aktif'}</span><p>Semua pesanan, dalam satu tempat.</p><a class="btn light full" href="#langganan">Rp30.000 / bulan ${icon('arrow')}</a></div><nav class="nav" aria-label="Pengaturan">${navLink('pengaturan','Pengaturan','settings')}${navLink('desain','Sistem desain','design')}${navLink('masuk','Layar masuk','logout')}</nav></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">Ruang kerja <span style="margin:0 10px;color:#a0b2a7">/</span> ${esc(({ringkasan:'Ringkasan',pesanan:'Pesanan',kalender:'Kalender',produk:'Produk',pengaturan:'Pengaturan',langganan:'Langganan',desain:'Sistem desain',lainnya:'Lainnya'})[route]||'PesanKue')}</span><div class="topbar-actions"><span class="demo-pill">Mode demo</span><a class="btn secondary" href="#toko">${icon('store')}Lihat toko</a><span class="avatar">${esc((state.shop.owner||'N')[0])}</span></div></header><main class="content" id="main">${isExpired()?`<div class="notice">${icon('info')}<div><b>Masa aktif toko berakhir.</b><p>Pesanan lama tetap bisa diselesaikan. Perpanjang untuk menerima pesanan baru.</p></div><a href="#langganan" class="btn secondary">Perpanjang</a></div>`:''}${body}<div class="view-note">Prototipe • Data contoh tersimpan di browser ini. Gunakan data fiktif saat mencoba.</div></main></div><nav class="mobile-nav" aria-label="Navigasi HP">${navLink('ringkasan','Ringkasan','home')}${navLink('pesanan','Pesanan','orders')}${navLink('kalender','Kalender','calendar')}${navLink('produk','Produk','box')}${navLink('lainnya','Lainnya','more')}</nav>`}
function weekStrip(){let d=new Date(today+'T12:00:00+07:00');let offset=(d.getDay()+6)%7;return `<div class="week-strip">${Array.from({length:7},(_,i)=>{let day=addDay(i-offset);return `<button class="day-chip ${day===today?'selected':''}" data-action="calendar-date" data-id="${day}"><span>${new Intl.DateTimeFormat('id-ID',{weekday:'short',timeZone:'Asia/Jakarta'}).format(new Date(day+'T12:00:00+07:00'))}</span><b>${Number(day.slice(-2))}</b></button>`}).join('')}</div>`}
function agenda(day){const list=state.orders.filter(o=>o.date===day&&(ACTIVE.includes(o.status)||(route==='kalender'&&o.status==='done'))).sort((a,b)=>a.time.localeCompare(b.time));return list.length?list.map(o=>`<div class="agenda-item"><span class="time">${o.time}</span><div class="agenda-line"><button class="btn ghost" style="padding:0;min-height:24px;text-align:left" data-action="detail" data-id="${o.id}">${esc(o.name)}</button><p>${o.items.map(x=>`${x.qty} × ${esc(x.name)}`).join(', ')}</p>${o.items.some(x=>x.note)?`<p class="small">${o.items.filter(x=>x.note).map(x=>esc(x.note)).join('; ')}</p>`:''}<span class="small muted">${o.method}</span> ${badge(o)}</div></div>`).join(''):empty('Jadwal masih kosong','Pesanan yang dikonfirmasi akan muncul di agenda.')}
function dashboard(){const pending=state.orders.filter(o=>o.status==='pending'),activeToday=state.orders.filter(o=>o.date===today&&ACTIVE.includes(o.status)),due=state.orders.filter(o=>['confirmed','processing','ready','done'].includes(o.status)&&balance(o)>0),incoming=state.orders.flatMap(o=>o.payments).filter(p=>p.date===today&&p.type!=='refund').reduce((s,p)=>s+p.amount,0);return heading(`Selamat datang, ${esc(state.shop.owner)}!`,'Yuk, siapkan pesanan hari ini.',addOrderBtn())+`<div class="stats">${[['Pesanan hari ini',activeToday.length,'Siap dijadwalkan','calendar',''],['Perlu konfirmasi',pending.length,'Pesanan baru masuk','clock',''],['Tagihan belum lunas',money(due.reduce((s,o)=>s+balance(o),0)),`${due.length} pesanan perlu dilunasi`,'orders',''],['Pembayaran masuk',money(incoming),'Hari ini · pembayaran tercatat','wallet','primary']].map(([label,v,sub,ic,c])=>`<article class="stat ${c}"><div class="flex between"><span class="label">${label}</span><span class="stat-icon">${icon(ic)}</span></div><strong>${v}</strong><span class="small muted">${sub}</span></article>`).join('')}</div>${pending.length?`<div class="notice">${icon('clock')}<div style="flex:1"><b>${pending.length} pesanan menunggu kabar darimu</b><p>Periksa jadwal dan detail pesanan sebelum mengonfirmasi.</p></div><button class="btn secondary" data-action="filter-pending">Lihat pesanan ${icon('arrow')}</button></div>`:''}<div class="main-grid"><section class="panel"><div class="panel-head"><div><h2>Pesanan terbaru</h2><p>Semua detail, tanpa terlewat.</p></div><a href="#pesanan" class="btn ghost">Lihat semua ${icon('arrow')}</a></div>${orderRows([...state.orders].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,5))}<div class="panel-footer">Pesanan dari link toko dan WhatsApp terkumpul di sini.</div></section><section class="panel"><div class="panel-head"><div><h2>Agenda hari ini</h2><p>${dateLabel(today)}</p></div>${icon('calendar')}</div>${weekStrip()}<div class="panel-pad">${agenda(today)}</div><div class="panel-footer"><a href="#kalender">Buka kalender produksi ${icon('arrow')}</a></div></section></div>`}
function filteredOrders(){return state.orders.filter(o=>(filters.status==='all'||o.status===filters.status)&&(filters.payment==='all'||paymentStatus(o)===filters.payment)&&(o.name+' '+o.id).toLowerCase().includes(filters.search.toLowerCase()))}
function ordersPage(){return heading('Pesanan','Dari pesanan baru hingga selesai.',addOrderBtn())+`<div class="toolbar"><div class="search">${icon('search')}<input id="order-search" aria-label="Cari pesanan" placeholder="Cari nama pelanggan atau nomor pesanan" value="${esc(filters.search)}"></div><select id="order-status" aria-label="Filter status pesanan"><option value="all">Semua status</option>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${filters.status===k?'selected':''}>${v}</option>`).join('')}</select><select id="order-payment" aria-label="Filter pembayaran"><option value="all">Semua pembayaran</option>${[['unpaid','Belum dibayar'],['partial','Dibayar sebagian'],['paid','Lunas']].map(([k,v])=>`<option value="${k}" ${filters.payment===k?'selected':''}>${v}</option>`).join('')}</select>${btn(icon('download')+'Ekspor','export','secondary')}</div><section class="panel"><div class="panel-head"><h2 id="order-count">${filteredOrders().length} pesanan</h2><button class="btn ghost" data-action="reset-filter">Reset filter</button></div><div id="orders-list">${orderRows(filteredOrders())}</div></section>`}
function photo(p){return `<div class="product-photo ${esc(p.photo||'brownies')} ${p.image?'custom':''}"><img src="${p.image?esc(p.image):'bakery.png'}" alt="${esc(p.name)}${p.image?'':' — foto ilustrasi produk'}" loading="lazy"></div>`}
function productCards(publicMode=false){let prods=state.products.filter(p=>(!publicMode||p.active)&&p.name.toLowerCase().includes(productSearch.toLowerCase()));return prods.length?`<div class="product-grid">${prods.map(p=>`<article class="product-card">${photo(p)}<div class="product-body">${!publicMode?`<span class="badge ${p.active?'paid':'unpaid'}">${p.active?'Aktif':'Nonaktif'}</span>`:''}<h3>${esc(p.name)}</h3><p>${esc(p.description)}</p><div class="product-price">${money(Math.min(...p.variants.map(v=>v.price)))}</div>${publicMode?`<label class="small" for="variant-${p.id}" style="margin-top:12px">${p.variants.length>1?'Pilih variasi':'Pilihan produk'}</label><select id="variant-${p.id}">${p.variants.map((v,i)=>`<option value="${i}">${esc(v.name)} · ${money(v.price)}</option>`).join('')}</select><button class="btn secondary full" style="margin-top:12px" data-action="add-cart" data-id="${p.id}" ${isExpired()?'disabled':''}>${icon('plus')}Tambah</button>`:`<div class="flex">${btn(icon('edit')+'Ubah','edit-product','secondary',p.id)}${btn(p.active?'Nonaktifkan':'Aktifkan','toggle-product','ghost',p.id)}</div>`}</div></article>`).join('')}</div>`:empty('Produk belum tersedia',publicMode?'Toko belum memiliki produk aktif.':'Tambahkan produk pertamamu untuk mulai menerima pesanan.')}
function productsPage(){return heading('Produk','Katalog kue untuk pelangganmu.',btn(icon('plus')+'Tambah produk','new-product'))+`<div class="toolbar"><div class="search">${icon('search')}<input id="product-search" value="${esc(productSearch)}" aria-label="Cari produk" placeholder="Cari produk"></div><span class="small muted">${state.products.filter(p=>p.active).length} produk aktif</span></div><div id="product-list">${productCards()}</div>`}
function calendarPage(){const first=new Date(calendarMonth+'-01T12:00:00+07:00'),start=(first.getDay()+6)%7,count=new Date(Number(calendarMonth.slice(0,4)),Number(calendarMonth.slice(5)),0).getDate(),items=recap(state.orders,calendarDate);return heading('Kalender produksi','Jadwal berdasarkan tanggal pengambilan atau pengiriman.',addOrderBtn())+`<div class="main-grid"><section class="panel panel-pad"><div class="flex between" style="margin-bottom:20px"><h2 style="margin:0">${new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric',timeZone:'Asia/Jakarta'}).format(first)}</h2><div class="flex">${btn(icon('back'),'month-prev','secondary icon-only')}${btn('Hari ini','calendar-today','secondary')}${btn(icon('arrow'),'month-next','secondary icon-only')}</div></div><div class="calendar-grid">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div class="calendar-head">${x}</div>`).join('')}${Array.from({length:start},()=>'<div class="calendar-day blank"></div>').join('')}${Array.from({length:count},(_,i)=>{let day=calendarMonth+'-'+String(i+1).padStart(2,'0'),n=state.orders.filter(o=>o.date===day&&ACTIVE.includes(o.status)).length;return `<button class="calendar-day ${day===calendarDate?'selected':''} ${day===today?'today':''}" data-action="calendar-date" data-id="${day}" aria-label="${dateLabel(day)}, ${n} pesanan"><b>${i+1}</b>${n?`<small>${n} pesanan</small>`:''}</button>`}).join('')}</div><p class="schedule-note">Rekap produksi berisi pesanan dikonfirmasi, diproses, dan siap.</p></section><div class="stack"><section class="panel panel-pad"><h2>${dateLabel(calendarDate)}</h2>${agenda(calendarDate)}</section><section class="panel panel-pad"><h2>Yang perlu disiapkan</h2>${items.length?items.map(x=>`<div class="tally"><span>${esc(x.name)}</span><b>${x.qty}</b></div>`).join(''):'<p class="muted small">Belum ada produk untuk tanggal ini.</p>'}</section></div></div>`}
function settingsPage(){const s=state.shop;return heading('Pengaturan toko','Informasi yang tampil di katalog dan tagihan.')+`<form id="settings-form" class="panel panel-pad" style="max-width:860px"><section class="form-section"><h2 class="section-title">Profil toko</h2><div class="form-grid">${field('Nama toko','shop-name',s.name,'text','required minlength="2" maxlength="60"')}${field('Nama pemilik','owner',s.owner,'text','required maxlength="60"')}${field('Nomor WhatsApp','shop-wa',s.wa,'tel','required')}<div><label for="timezone">Zona waktu</label><select name="timezone" id="timezone"><option value="Asia/Jakarta">WIB — Asia/Jakarta</option></select><p class="field-help">Prototipe menggunakan WIB. WITA dan WIT direncanakan untuk produksi.</p></div><div class="span2"><label for="address">Alamat pengambilan</label><textarea id="address" name="address" required maxlength="300">${esc(s.address)}</textarea></div></div></section><section class="form-section"><h2 class="section-title">Penyerahan pesanan</h2><div class="check-grid"><label class="checkrow"><input type="checkbox" name="pickup" ${s.pickup?'checked':''}>Ambil sendiri</label><label class="checkrow"><input type="checkbox" name="delivery" ${s.delivery?'checked':''}>Dikirim</label></div><p class="field-help">Ongkir ditentukan saat pemilik mengonfirmasi pesanan.</p></section><section class="form-section"><h2 class="section-title">Pembayaran</h2><div class="form-grid">${field('Nama bank','bank',s.bank,'text','required maxlength="60"')}${field('Nomor rekening','account',s.account,'text','required inputmode="numeric" maxlength="30"')}${field('Atas nama','holder',s.holder,'text','required maxlength="80"')}${field('DP pesanan (%)','dp',s.dp,'number','required min="0" max="100" step="1"')}</div><p class="field-help">Gunakan data contoh. Jangan melakukan transfer uang pada prototipe ini.</p></section><div class="error" id="settings-error" role="alert"></div><div class="modal-actions"><button class="btn" id="settings-save" disabled>Simpan perubahan</button></div></form>`}
function subscriptionPage(){const s=state.subscription;return heading('Langganan','Satu paket sederhana untuk toko kecilmu.')+`<div class="main-grid"><section class="panel panel-pad"><span class="badge ${isExpired()?'cancelled':'paid'}">${isExpired()?'Masa aktif habis':s.status==='trial'?'Trial aktif':'Langganan aktif'}</span><h2 style="margin-top:18px">${isExpired()?'Aktifkan kembali tokomu':'Semua pesanan tetap tertata'}</h2><p class="muted">${isExpired()?'Perpanjang untuk menerima pesanan baru.':'Masa aktif sampai '+dateLabel(s.end)+'.'}</p><div class="divider"></div><div class="price-hero">Rp30.000<small> / bulan</small></div><p class="muted small" style="margin-top:10px">Satu pemilik · satu toko · dibayar di muka</p><ul class="checklist">${['Katalog dan link pemesanan','Pesanan manual dari WhatsApp','Kalender serta rekap produksi','Catatan DP dan pelunasan','Ekspor riwayat pesanan'].map(x=>`<li>${icon('check')}${x}</li>`).join('')}</ul>${btn(s.invoice?'Lihat tagihan perpanjangan':'Perpanjang satu bulan','renew','full')}<p class="field-help">Demo tagihan saja. Tidak ada pembayaran nyata.</p></section><div class="stack"><section class="panel panel-pad"><h2>Cara perpanjang</h2><ol style="padding-left:22px;font-size:14px"><li style="margin-bottom:12px">Buat tagihan langganan.</li><li style="margin-bottom:12px">Transfer dan kirim bukti kepada admin layanan.</li><li>Admin memverifikasi, lalu masa aktif diperpanjang.</li></ol><p class="small muted">Pada produk nyata, verifikasi dilakukan oleh operator layanan.</p></section><section class="panel panel-pad"><h2>Simulasi masa aktif</h2><p class="small muted">Coba perilaku aplikasi ketika langganan habis atau aktif kembali.</p><div class="flex wrap">${btn('Simulasikan habis','expire','secondary')}${btn('Aktifkan demo','activate','secondary')}</div></section></div></div>`}
function publicShell(body){return `<header class="public-header">${brand()}<div class="flex"><span class="demo-pill">Toko contoh</span><a class="btn secondary" href="#ringkasan">Dashboard pemilik</a></div></header><main class="public-main" id="main">${body}<p class="public-footer">Dibuat dengan PesanKue · Prototipe, bukan toko aktif</p></main>`}
function shopPage(){return `<section class="shop-hero"><img src="bakery.png" alt="Brownies, strawberry cake, dan cookies — ilustrasi katalog"><div class="shop-hero-copy"><span class="small" style="letter-spacing:2px">DARI DAPUR, DENGAN HATI</span><h1 style="margin-top:12px">${esc(state.shop.name)}</h1><p>Kue favorit untuk momen kecil yang berarti.</p><div class="shop-meta">${state.shop.pickup?'<span>Ambil sendiri</span>':''}${state.shop.delivery?'<span>Bisa dikirim</span>':''}</div></div></section>${isExpired()?'<div class="notice">Toko sedang menutup penerimaan pesanan baru.</div>':'<div class="notice green">'+icon('calendar')+'<span>Pesan untuk tanggal pilihanmu. Jadwal dan total akhir dikonfirmasi oleh toko.</span></div>'}<div class="page-heading"><div><h2 style="margin-bottom:4px">Pilihan dari dapur kami</h2><p>Dibuat sesuai pesanan, dinikmati bersama.</p></div></div>${productCards(true)}${cart.length?`<button class="cart-float" data-action="checkout"><span><b>${cart.reduce((s,x)=>s+x.qty,0)} produk di keranjang</b><small>${money(cart.reduce((s,x)=>s+x.qty*x.price,0))} · sebelum ongkir</small></span><span class="flex">Lihat pesanan ${icon('arrow')}</span></button>`:''}`}
function fulfillmentFields(o={}){return `${field('Nama pelanggan','customer-name',o.name||'','text','required minlength="2" maxlength="80"')}${field('Nomor WhatsApp','customer-wa',o.wa||'','tel','required placeholder="Contoh: 0812…"')}${field('Tanggal penyerahan','order-date',o.date||addDay(1),'date',`required min="${today}"`)}${field('Jam penyerahan (WIB)','order-time',o.time||'10:00','time','required')}<div><label for="fulfillment">Metode penyerahan</label><select id="fulfillment" name="fulfillment">${state.shop.pickup?`<option ${o.method==='Ambil sendiri'?'selected':''}>Ambil sendiri</option>`:''}${state.shop.delivery?`<option ${o.method==='Dikirim'?'selected':''}>Dikirim</option>`:''}</select></div><div id="delivery-address-field" class="${(o.method|| (state.shop.pickup?'Ambil sendiri':'Dikirim'))==='Dikirim'?'':'hidden'}"><label for="delivery-address">Alamat pengiriman</label><textarea id="delivery-address" name="delivery-address" maxlength="300" ${(o.method==='Dikirim'||(!o.method&&!state.shop.pickup))?'required':''}>${esc(o.address||'')}</textarea></div>`}
function checkoutPage(){if(!cart.length)return empty('Keranjang masih kosong','Pilih kue terlebih dahulu.')+'<a class="btn" href="#toko">Kembali ke katalog</a>';return heading('Lengkapi pesananmu','Jadwal dan total akhir akan dikonfirmasi toko.','<a class="btn secondary" href="#toko">'+icon('back')+'Katalog</a>')+`<form id="checkout-form"><div class="checkout-grid"><section class="panel panel-pad"><h2>Data dan jadwal</h2><div class="form-grid">${fulfillmentFields()}</div><div style="margin-top:20px"><label for="customer-note">Catatan pesanan</label><textarea name="customer-note" id="customer-note" maxlength="300" placeholder="Contoh: tulisan pada kue atau kebutuhan khusus"></textarea></div><p class="field-help">Data digunakan toko untuk memproses pesanan. Gunakan data fiktif pada demo ini.</p></section><section class="panel panel-pad"><h2>Ringkasan pesanan</h2>${cart.map((x,i)=>`<div class="line-item"><div><b>${esc(x.name)}</b><p>${esc(x.variant)}</p><div class="flex" style="margin-top:10px"><button type="button" class="btn secondary icon-only" data-action="cart-minus" data-id="${i}" aria-label="Kurangi ${esc(x.name)}">−</button><span>${x.qty}</span><button type="button" class="btn secondary icon-only" data-action="cart-plus" data-id="${i}" aria-label="Tambah ${esc(x.name)}">+</button></div></div><strong class="small amount">${money(x.qty*x.price)}</strong></div>`).join('')}<div class="summary-line total"><span>Subtotal</span><span>${money(cart.reduce((s,x)=>s+x.qty*x.price,0))}</span></div><p class="field-help">Ongkir dihitung saat konfirmasi jika dikirim. Jangan transfer sebelum pesanan dikonfirmasi.</p><label class="checkrow" style="margin:18px 0"><input type="checkbox" name="consent" required>Saya memahami pesanan menunggu konfirmasi toko.</label><div class="error" id="checkout-error" role="alert"></div><button class="btn full" ${isExpired()?'disabled':''}>Kirim pesanan ${icon('arrow')}</button></section></div></form>`}
function summary(o){return `<div class="summary-line"><span>Subtotal produk</span><span>${money(total(o)-o.shipping)}</span></div><div class="summary-line"><span>Ongkir</span><span>${o.status==='pending'&&o.method==='Dikirim'?'Menunggu konfirmasi':money(o.shipping)}</span></div><div class="summary-line total"><span>${o.status==='pending'?'Perkiraan total':'Total pesanan'}</span><span>${money(total(o))}</span></div>${o.status!=='pending'?`<div class="summary-line"><span>DP diminta (${o.dpPercent}%)</span><span>${money(Math.ceil(total(o)*o.dpPercent/100))}</span></div><div class="summary-line"><span>Pembayaran bersih</span><span>${money(paid(o))}</span></div><div class="summary-line balance"><span>${o.status==='cancelled'?'Saldo pesanan awal':'Sisa tagihan'}</span><span>${money(balance(o))}</span></div>${paid(o)>total(o)?`<div class="summary-line"><span>Kelebihan pembayaran</span><b>${money(paid(o)-total(o))}</b></div>`:''}`:''}`}
function trackPage(token){const o=state.orders.find(x=>x.token===token);if(!o)return empty('Pesanan tidak ditemukan','Link demo hanya bekerja pada browser yang menyimpan pesanan tersebut.')+'<a class="btn secondary" href="#toko">Kembali ke toko</a>';const captions={pending:'Pesananmu sudah masuk',confirmed:'Pesanan sudah dikonfirmasi',processing:'Kue sedang disiapkan',ready:'Pesananmu sudah siap',done:'Terima kasih sudah memesan',cancelled:'Pesanan dibatalkan',rejected:'Pesanan belum dapat diterima'};return `<div class="status-container"><section class="panel"><div class="status-hero"><div class="status-symbol">${icon(o.status==='pending'?'clock':'check')}</div><span class="small muted">${o.id}</span><h1 style="margin:10px 0 14px">${captions[o.status]}</h1>${badge(o)}<p class="muted small" style="margin-top:16px">${o.status==='pending'?'Tunggu konfirmasi toko sebelum melakukan pembayaran.':'Lihat rincian dan perkembangan pesanan di halaman ini.'}</p></div><div class="panel-pad" style="border-top:1px solid var(--border)"><div class="detail-info"><b>${esc(o.name)}</b><p>${o.method} · ${dateLabel(o.date)} · ${o.time} WIB</p><p>${esc(o.method==='Dikirim'?o.address:state.shop.address)}</p></div>${o.items.map(x=>`<div class="line-item"><div><b>${x.qty} × ${esc(x.name)}</b><p>${esc(x.variant)}</p>${x.note?`<p>Catatan: ${esc(x.note)}</p>`:''}</div><span class="amount small">${money(x.qty*x.price)}</span></div>`).join('')}${summary(o)}${o.status==='cancelled'||o.status==='rejected'?`<div class="notice" style="margin-top:20px">${esc(o.reason||'Hubungi toko untuk informasi lebih lanjut.')} ${o.status==='cancelled'?'Penyelesaian pembayaran disepakati langsung dengan toko.':''}</div>`:o.status!=='pending'?`<div class="notice green" style="margin-top:20px"><div><b>Informasi pembayaran contoh</b><p>${esc((o.bank||state.shop).bank)} · ${esc((o.bank||state.shop).account)}<br>a.n. ${esc((o.bank||state.shop).holder)}</p><p>Jangan transfer uang. Halaman ini hanya demonstrasi.</p></div></div>`:''}<div class="line-actions">${btn(icon('copy')+'Salin link status','copy-track','secondary',o.id)}<a class="btn secondary" href="#toko">Kembali ke katalog</a></div></div></section></div>`}
function designPage(){const swatches=[['Brand','#153F35'],['Canvas','#F4F6F5'],['Surface','#FFFFFF'],['Text','#172D27'],['Muted','#5E6D67'],['Border','#DCE4DF'],['Accent','#F2CC64'],['Danger','#A62F38']];return heading('Sistem desain','Fondasi visual dan layar PesanKue.','<span class="badge paid">Versi 1.0</span>')+`<section class="panel panel-pad showcase"><h2>01 / Warna</h2><div class="swatches">${swatches.map(([n,c])=>`<div class="swatch"><div class="swatch-color" style="background:${c}"></div><p><b>${n}</b>${c}</p></div>`).join('')}</div></section><div class="main-grid"><section class="panel panel-pad showcase"><h2>02 / Tipografi</h2><p class="muted small">System sans-serif · line height 1,5</p><h1>Pesanan yang tertata.</h1><h2>Jadwal produksi hari ini</h2><p>Semua detail penting, mudah ditemukan.</p><span class="small muted">Judul 30 px · panel 20 px · isi 16 px · label 14 px</span></section><section class="panel panel-pad showcase"><h2>03 / Tombol</h2><div class="flex wrap">${btn('Utama','demo-toast')}${btn('Sekunder','demo-toast','secondary')}${btn('Batalkan','demo-toast','danger')}<button class="btn" disabled>Nonaktif</button></div><p class="field-help" style="margin-top:20px">Target sentuh 44 px · radius 10 px · fokus keyboard terlihat</p></section></div><section class="panel panel-pad showcase"><h2>04 / Status</h2><div class="flex wrap">${Object.keys(STATUS).map(status=>badge({status})).join('')}</div><div class="divider"></div><div class="flex wrap"><span class="badge unpaid">Belum dibayar</span><span class="badge partial">Dibayar sebagian</span><span class="badge paid">Lunas</span></div><p class="field-help">Status pesanan dan status pembayaran selalu dipisahkan.</p></section><section class="panel panel-pad showcase"><h2>05 / Form dan keadaan</h2><div class="form-grid">${field('Nama produk','sample-name','Brownies Panggang','text','readonly')}${field('Harga jual','sample-price','45.000','text','readonly')}<div><label for="sample-error">Nomor WhatsApp</label><input id="sample-error" value="081" aria-invalid="true" aria-describedby="sample-error-help" readonly style="border-color:var(--danger)"><div id="sample-error-help" class="error">Periksa kembali nomor WhatsApp.</div></div><div><label>Keadaan kosong</label><div class="detail-info small">Belum ada pesanan pada tanggal ini.</div></div></div></section><section class="panel panel-pad showcase"><h2>06 / Jelajahi seluruh layar</h2><div class="screen-links">${[['ringkasan','Ringkasan','home'],['pesanan','Pesanan dan detail','orders'],['kalender','Kalender produksi','calendar'],['produk','Katalog produk','box'],['pengaturan','Pengaturan toko','settings'],['langganan','Langganan','card'],['toko','Toko pelanggan','store'],['masuk','Masuk','logout'],['daftar','Daftar','plus'],['onboarding','Penyiapan toko','settings']].map(([r,t,i])=>`<a class="screen-link" href="#${r}">${icon(i)}${t}${icon('arrow')}</a>`).join('')}</div></section><section class="panel panel-pad"><h2>07 / Skenario uji prototipe</h2><ol style="padding-left:22px;font-size:14px"><li>Buka toko, pilih produk, dan kirim pesanan.</li><li>Buka Pesanan, konfirmasi, lalu catat DP.</li><li>Periksa kalender, mulai produksi, dan tandai siap.</li><li>Catat pelunasan lalu selesaikan pesanan.</li></ol><div class="notice" style="margin-bottom:16px">Data tersimpan di browser ini. Login, billing dan status pelanggan adalah simulasi lokal; backend belum terhubung.</div>${btn('Reset seluruh data contoh','reset-demo','danger')}</section>`}
function authPage(register=false){return `<div class="auth-layout"><section class="auth-art">${brand()}<div><h1>Lebih tenang menerima pesanan.</h1><p>Jadwal rapi. Pembayaran tercatat.<br>Kamu bisa fokus membuat kue.</p><img src="bakery.png" alt="Pilihan kue dari dapur rumahan"></div><span class="small">Rp30.000 per bulan · trial 7 hari</span></section><main class="auth-form" id="main"><div class="auth-form-inner">${brand()}<h1>${register?'Mulai cerita tokomu':'Selamat datang kembali'}</h1><p class="muted">${register?'Siapkan ruang untuk semua pesananmu.':'Masuk untuk melihat pesanan hari ini.'}</p><div class="auth-demo">Simulasi tampilan akun. Gunakan data fiktif dan password contoh. Tidak membuat akun sungguhan.</div><form id="${register?'register':'login'}-form">${register?field('Nama pemilik','auth-name','','text','required maxlength="60"'):''}${field('Email','auth-email','','email','required placeholder="nama@contoh.com"')}${field('Password','auth-password','','password','required minlength="10" autocomplete="off" placeholder="Minimal 10 karakter"')}${register?field('Konfirmasi password','auth-confirm','','password','required minlength="10" autocomplete="off"'):''}<div class="error" id="auth-error" role="alert"></div><button class="btn full">${register?'Lanjutkan penyiapan':'Masuk ke demo'} ${icon('arrow')}</button></form>${!register?btn('Lupa password?','forgot','ghost'):''}<p class="small muted" style="margin-top:25px">${register?'Sudah punya akun? <a href="#masuk"><b>Masuk</b></a>':'Belum punya akun? <a href="#daftar"><b>Daftar</b></a>'}</p><a class="btn secondary full" href="#ringkasan">Langsung jelajahi demo</a></div></main></div>`}
function onboardingPage(){let s={...state.shop,...setupDraft};return `<div style="max-width:820px;margin:35px auto;padding:0 20px">${brand()}<div class="panel panel-pad" style="margin-top:28px"><h1>Siapkan toko pertamamu</h1><p class="muted">Trial 7 hari dimulai setelah toko selesai dibuat.</p><div class="onboarding-steps"><span class="${onboardingStep===1?'active':''}">1. Profil toko</span><span class="${onboardingStep===2?'active':''}">2. Pembayaran</span><span class="${onboardingStep===3?'active':''}">3. Konfirmasi</span></div><form id="onboarding-form">${onboardingStep===1?`<div class="form-grid">${field('Nama toko','setup-name',s.name,'text','required minlength="2" maxlength="60"')}${field('Nama pemilik','setup-owner',s.owner,'text','required maxlength="60"')}${field('Nomor WhatsApp','setup-wa',s.wa,'tel','required')}<div><label for="setup-address">Alamat toko</label><textarea name="setup-address" id="setup-address" required maxlength="300">${esc(s.address)}</textarea></div></div>`:onboardingStep===2?`<div class="form-grid">${field('Nama bank','setup-bank',s.bank,'text','required')}${field('Nomor rekening','setup-account',s.account,'text','required inputmode="numeric"')}${field('Atas nama','setup-holder',s.holder,'text','required')}${field('DP (%)','setup-dp',s.dp,'number','required min="0" max="100"')}</div><p class="field-help">Gunakan rekening contoh pada prototipe.</p>`:`<div class="detail-info"><h2>${esc(s.name)}</h2><p>Pemilik: ${esc(s.owner)}</p><p>${esc(s.address)}</p><p>DP ${s.dp}% · ${esc(s.bank)}</p></div><label class="checkrow" style="margin-top:20px"><input type="checkbox" required>Saya memahami penyiapan ini hanya simulasi.</label><p class="field-help">Katalog akan memakai tiga produk contoh yang dapat diubah.</p>`}<div class="error" id="setup-error" role="alert"></div><div class="modal-actions">${onboardingStep>1?'<button type="button" class="btn secondary" data-action="setup-back">Kembali</button>':'<a class="btn secondary" href="#ringkasan">Kembali ke demo</a>'}<button class="btn">${onboardingStep===3?'Buat toko demo':'Lanjutkan'} ${icon('arrow')}</button></div></form></div></div>`}
function morePage(){return heading('Lainnya','Kelola toko dan jelajahi prototipe.')+`<section class="panel panel-pad"><div class="screen-links">${[['pengaturan','Pengaturan','settings'],['langganan','Langganan','card'],['desain','Sistem desain','design'],['toko','Lihat toko','store'],['masuk','Layar masuk','logout']].map(([r,t,i])=>`<a class="screen-link" href="#${r}">${icon(i)}${t}</a>`).join('')}</div></section>`}
function render(){route=(location.hash.slice(1).split('/')[0]||'ringkasan');const views={ringkasan:dashboard,pesanan:ordersPage,kalender:calendarPage,produk:productsPage,pengaturan:settingsPage,langganan:subscriptionPage,desain:designPage,lainnya:morePage};let html;if(views[route])html=shell(views[route]());else if(route==='toko')html=publicShell(shopPage());else if(route==='checkout')html=publicShell(checkoutPage());else if(route==='status')html=publicShell(trackPage(location.hash.split('/')[1]||state.lastToken));else if(route==='masuk'||route==='daftar')html=authPage(route==='daftar');else if(route==='onboarding')html=onboardingPage();else html=shell(empty('Halaman tidak ditemukan')+'<a class="btn" href="#ringkasan">Kembali ke ringkasan</a>');$('#app').innerHTML=html;document.title=`${({ringkasan:'Ringkasan',pesanan:'Pesanan',kalender:'Kalender',produk:'Produk',toko:state.shop.name,status:'Status pesanan',desain:'Sistem desain'})[route]||'PesanKue'} — PesanKue`}
let currentOrder=null,productEditing=null,productImage=null,editOrderId=null;
function showDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return;currentOrder=id;const actions={pending:['Konfirmasi pesanan','confirmed'],confirmed:['Mulai produksi','processing'],processing:['Tandai siap','ready'],ready:['Selesaikan pesanan','done']};openModal('Detail pesanan '+o.id,`<div class="flex wrap" style="margin-bottom:22px">${badge(o)}${payBadge(o)}<span class="small muted">${esc(o.source)}</span></div><div class="detail-grid"><div><div class="detail-info"><b>${esc(o.name)}</b><p>${esc(o.wa)}</p><p>${o.method} · ${dateLabel(o.date)} · ${o.time} WIB</p><p>${esc(o.method==='Dikirim'?o.address:state.shop.address)}</p></div>${o.items.map(x=>`<div class="line-item"><div><b>${x.qty} × ${esc(x.name)}</b><p>${esc(x.variant)}</p>${x.note?`<p>Catatan: ${esc(x.note)}</p>`:''}</div><strong class="small amount">${money(x.qty*x.price)}</strong></div>`).join('')}${o.reason?`<p class="notice" style="margin-top:18px">${esc(o.reason)}</p>`:''}<h3 style="margin-top:25px">Riwayat pesanan</h3><ul class="timeline">${[...o.events].reverse().map(e=>`<li>${esc(e.label)}<small>${dateLabel(dateISO(new Date(e.at)),true)} · ${timeLabel(e.at)} WIB</small></li>`).join('')}</ul></div><div>${summary(o)}<div class="divider"></div><h3>Pembayaran tercatat</h3>${o.payments.length?o.payments.map(p=>`<div class="summary-line"><span>${p.type==='refund'?'Pengembalian':'Pembayaran'}<small class="muted" style="display:block">${dateLabel(p.date,true)} · ${esc(p.method)}</small>${p.note?`<small class="muted">${esc(p.note)}</small>`:''}</span><b>${p.type==='refund'?'−':''}${money(p.amount)}</b></div>`).join(''):'<p class="small muted">Belum ada pembayaran.</p>'}${!['pending','rejected','cancelled'].includes(o.status)?btn(icon('plus')+'Catat pembayaran','payment','secondary full',id):''}${paid(o)>0?'<div style="margin-top:10px">'+btn('Catat pengembalian','refund','ghost full',id)+'</div>':''}${o.status==='cancelled'?'<p class="field-help">Saldo awal tidak ditagih otomatis. Sepakati uang ditahan atau dikembalikan dengan pelanggan.</p>':''}<div class="divider"></div><button class="btn secondary full" data-action="track" data-id="${id}">${icon('link')}Lihat halaman pelanggan</button>${!['pending','rejected','cancelled'].includes(o.status)?`<button class="btn ghost full" style="margin-top:8px" data-action="share" data-id="${id}">${icon('copy')}Siapkan pesan WhatsApp</button>`:''}</div></div><div class="modal-actions">${['pending','confirmed','processing','ready'].includes(o.status)?btn(icon('edit')+'Ubah pesanan','edit-order','secondary',id):''}${o.status==='pending'?btn('Tolak','reject','danger',id):ACTIVE.includes(o.status)?btn('Batalkan','cancel','danger',id):''}${actions[o.status]?`<button class="btn" data-action="transition" data-id="${id}" data-next="${actions[o.status][1]}">${actions[o.status][0]} ${icon('arrow')}</button>`:''}</div>`)}
function addEvent(o,label){o.events.push({label,at:new Date().toISOString()})}
function transitionDialog(id,next){const o=state.orders.find(x=>x.id===id);if(!o||!canTransition(o,next))return;currentOrder=id;if(next==='confirmed'){openModal('Konfirmasi pesanan',`<form id="confirm-form"><p class="muted small">Pastikan jadwal dan perubahan harga sudah disepakati dengan pelanggan.</p><div class="detail-info" style="margin-bottom:20px"><b>${esc(o.name)}</b><p>${dateLabel(o.date)} · ${o.time} WIB</p><p>Subtotal ${money(total(o)-o.shipping)}</p></div><div class="form-grid">${field('Ongkir (Rp)','confirm-shipping',o.shipping,'text',`required inputmode="numeric" data-money ${o.method==='Ambil sendiri'?'readonly':''}`)}${field('DP (%)','confirm-dp',state.shop.dp,'number','required min="0" max="100" step="1"')}</div><div id="confirm-totals" style="margin-top:14px"></div><label class="checkrow" style="margin-top:20px"><input type="checkbox" required>Detail dan jadwal sudah disepakati.</label><div class="error" id="confirm-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="detail" data-id="${id}">Kembali</button><button class="btn">Konfirmasi pesanan</button></div></form>`,true);updateConfirmTotals();return}
const warning=next==='processing'&&paid(o)<Math.ceil(total(o)*o.dpPercent/100)?'Pembayaran belum memenuhi DP. Tetap mulai produksi?':next==='done'&&balance(o)>0?`Sisa tagihan ${money(balance(o))} belum lunas. Pesanan tetap masuk daftar tagihan setelah selesai.`:`Ubah status pesanan menjadi ${STATUS[next]}?`;
openModal(STATUS[next],`<p>${warning}</p><div class="modal-actions">${btn('Kembali','detail','secondary',id)}<button class="btn" data-action="apply-transition" data-id="${id}" data-next="${next}">Ya, lanjutkan</button></div>`,true)}
function updateConfirmTotals(){const o=state.orders.find(o=>o.id===currentOrder);if(!o||!$('#confirm-totals'))return;const t=total(o)-o.shipping+Number($('#confirm-shipping').value.replaceAll('.','')||0),dp=Number($('#confirm-dp').value);$('#confirm-totals').innerHTML=`<div class="summary-line total"><span>Total</span><span>${money(t)}</span></div><div class="summary-line"><span>DP diminta</span><b>${money(Math.ceil(t*dp/100))}</b></div>`}
function paymentDialog(id,refund=false){const o=state.orders.find(x=>x.id===id);currentOrder=id;openModal(refund?'Catat pengembalian dana':'Catat pembayaran',`<form id="payment-form" data-type="${refund?'refund':'payment'}"><div class="notice ${refund?'':'green'}"><div>${refund?'Pengembalian dilakukan manual. Maksimal '+money(paid(o))+'.':'Periksa uang yang masuk sebelum mencatat. Sisa tagihan '+money(balance(o))+'.'}</div></div><div class="form-grid">${field('Nominal (Rp)','payment-amount',refund?'':balance(o),'text','required inputmode="numeric" data-money')}${field('Tanggal pembayaran','payment-date',today,'date',`required max="${today}"`)}<div><label for="payment-method">Metode</label><select name="payment-method" id="payment-method"><option>Transfer</option><option>Tunai</option></select></div>${field('Catatan opsional','payment-note','','text','maxlength="200"')}</div><div class="error" id="payment-error" role="alert"></div><div class="modal-actions">${btn('Kembali','detail','secondary',id)}<button class="btn">Simpan ${refund?'pengembalian':'pembayaran'}</button></div></form>`,true)}
function cancelDialog(id,reject=false){currentOrder=id;openModal(reject?'Tolak pesanan':'Batalkan pesanan',`<form id="cancel-form" data-status="${reject?'rejected':'cancelled'}"><p class="small muted">${reject?'Sampaikan alasan kepada pelanggan.':'Pesanan keluar dari rekap produksi. Pembayaran yang sudah masuk tetap tersimpan.'}</p><label for="cancel-reason">Alasan ${reject?'penolakan':'pembatalan'}</label><textarea name="reason" id="cancel-reason" required minlength="3" maxlength="300" placeholder="Contoh: jadwal produksi sudah penuh"></textarea><div class="modal-actions">${btn('Kembali','detail','secondary',id)}<button class="btn danger">${reject?'Tolak pesanan':'Batalkan pesanan'}</button></div></form>`,true)}
const parseAmount=v=>{const s=String(v).replaceAll('.','');if(!/^\d+$/.test(s)||!Number.isSafeInteger(Number(s)))throw new Error('Isi nominal rupiah tanpa desimal.');return Number(s)};
function readCustomer(form){const fd=new FormData(form),name=String(fd.get('customer-name')||'').trim(),wa=normalizeWA(fd.get('customer-wa')),date=String(fd.get('order-date')),time=String(fd.get('order-time')),method=String(fd.get('fulfillment')),address=String(fd.get('delivery-address')||'').trim();if(name.length<2)throw new Error('Isi nama pelanggan minimal 2 karakter.');if(!wa)throw new Error('Periksa nomor WhatsApp. Gunakan awalan 08 atau 62.');if(!date||!time||new Date(date+'T'+time+':00+07:00')<=new Date())throw new Error('Pilih tanggal dan jam penyerahan di masa depan.');if(method==='Dikirim'&&!address)throw new Error('Isi alamat pengiriman.');return {name,wa,date,time,method,address:method==='Dikirim'?address:''}}
function makeOrder(customer,items,source,confirmed=false,shipping=0){if(isExpired())throw new Error('Masa aktif habis. Perpanjang untuk membuat pesanan baru.');if(!items.length)throw new Error('Tambahkan minimal satu produk.');const snapshots=items.map(x=>{const p=state.products.find(p=>p.id===x.pid&&p.active),v=p?.variants.find(v=>v.name===x.variant);if(!p||!v)throw new Error('Produk atau variasi sudah tidak tersedia. Pilih kembali produk.');if(!Number.isInteger(x.qty)||x.qty<1||x.qty>999)throw new Error('Jumlah produk harus 1 sampai 999.');return {...x,name:p.name,price:v.price}});let n=Math.max(1040,...state.orders.map(o=>Number(o.id.slice(3))))+1;const o={...customer,id:'PK-'+n,token:uid(),items:snapshots,source,status:confirmed?'confirmed':'pending',shipping:customer.method==='Dikirim'?shipping:0,dpPercent:state.shop.dp,payments:[],events:[],createdAt:new Date().toISOString()};if(confirmed)o.bank={bank:state.shop.bank,account:state.shop.account,holder:state.shop.holder};addEvent(o,confirmed?'Pesanan manual dibuat dan dikonfirmasi':'Pesanan diterima melalui '+source);state.orders.unshift(o);state.lastToken=o.token;persist();return o}
function itemOptions(selected=''){return state.products.filter(p=>p.active).flatMap(p=>p.variants.map((v,i)=>`<option value="${p.id}:${i}" ${selected===p.id+':'+i?'selected':''}>${esc(p.name)} · ${esc(v.name)} · ${money(v.price)}</option>`)).join('')}
function draftRows(){return draftItems.map((x,i)=>{const p=state.products.find(p=>p.id===x.pid);const vi=p?.variants.findIndex(v=>v.name===x.variant)??0;return `<div class="item-edit"><div><label for="item-${i}">Produk dan variasi</label><select id="item-${i}" data-item-select="${i}">${!p?.active?`<option value="snapshot" selected>${esc(x.name)} · ${esc(x.variant)} (arsip)</option>`:''}${itemOptions(x.pid+':'+vi)}</select></div><div><label for="qty-${i}">Jumlah</label><input type="number" id="qty-${i}" data-item-qty="${i}" value="${x.qty}" min="1" max="999" required></div><button type="button" class="btn secondary icon-only" style="align-self:end" data-action="draft-remove" data-id="${i}" aria-label="Hapus produk">${icon('trash')}</button><div class="item-note"><label for="note-${i}">Catatan produk</label><input id="note-${i}" data-item-note="${i}" value="${esc(x.note||'')}" maxlength="300" placeholder="Tulisan pada kue, rasa, atau permintaan khusus"></div></div>`}).join('')}
function newOrderDialog(id=null){if(!id&&isExpired()){toast('Perpanjang langganan untuk menerima pesanan baru.');location.hash='langganan';return}const old=id?state.orders.find(o=>o.id===id):null;if(old&&!['pending',...ACTIVE].includes(old.status))return;editOrderId=id;draftItems=old?structuredClone(old.items):[];openModal(id?'Ubah pesanan '+id:'Tambah pesanan manual',`<form id="manual-form"><div class="form-grid">${fulfillmentFields(old||{})}</div><div class="divider"></div><h3>Produk pesanan</h3><div id="draft-items">${draftRows()}</div><button type="button" class="btn secondary" data-action="draft-add">${icon('plus')}Tambah produk</button><div class="form-grid" style="margin-top:20px">${field('Ongkir (Rp)','manual-shipping',old?.shipping||0,'text','required inputmode="numeric" data-money')}${!id?'<label class="checkrow"><input type="checkbox" name="confirmed">Langsung konfirmasi (sudah disepakati)</label>':'<p class="field-help">Sepakati perubahan dengan pelanggan terlebih dahulu. Harga item lama tetap dipertahankan.</p>'}</div><div class="error" id="manual-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close">Batal</button><button class="btn">${id?'Simpan perubahan':'Buat pesanan'}</button></div></form>`)}
function productDialog(id=null){const p=state.products.find(x=>x.id===id);productEditing=id;productImage=p?.image||null;openModal(id?'Ubah produk':'Tambah produk',`<form id="product-form"><div class="form-grid">${field('Nama produk','product-name',p?.name||'','text','required minlength="2" maxlength="80"')}<div><label for="product-photo">Foto contoh</label><select name="product-photo" id="product-photo">${[['brownies','Brownies'],['cake','Strawberry cake'],['cookies','Cookies']].map(([v,t])=>`<option value="${v}" ${p?.photo===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="span2"><label for="product-description">Deskripsi</label><textarea id="product-description" name="product-description" maxlength="1000">${esc(p?.description||'')}</textarea></div><div class="span2"><label for="product-image">Unggah foto sendiri (opsional)</label><input type="file" id="product-image" class="file-input" accept="image/jpeg,image/png,image/webp"><p class="field-help">Maksimal 5 MB. Foto demo tersimpan hanya di browser ini.</p></div></div><h3 style="margin-top:20px">Variasi dan harga</h3><div id="variant-fields">${(p?.variants||[{name:'Original',price:''}]).map((v,i)=>variantRow(v,i)).join('')}</div><button type="button" class="btn secondary" data-action="variant-add">${icon('plus')}Tambah variasi</button><div class="error" id="product-error" role="alert"></div><div class="modal-actions"><button type="button" class="btn secondary" data-action="close">Batal</button><button class="btn" id="product-save">Simpan produk</button></div></form>`)}
function variantRow(v,i){return `<div class="form-grid variant-row" style="margin-bottom:12px"><div><label for="variant-name-${i}">Nama variasi</label><input id="variant-name-${i}" class="variant-name" value="${esc(v.name)}" maxlength="60" required></div><div><label for="variant-price-${i}">Harga jual (Rp)</label><input id="variant-price-${i}" class="variant-price" value="${esc(v.price)}" inputmode="numeric" data-money required></div></div>`}
function shareDialog(id){const o=state.orders.find(o=>o.id===id);if(!o||['pending','rejected','cancelled'].includes(o.status))return;const msg=`Halo ${o.name}, berikut ringkasan pesanan ${o.id} di ${state.shop.name}.\n${o.items.map(x=>`${x.qty} × ${x.name} (${x.variant})`).join('\n')}\n${o.method}: ${dateLabel(o.date)}, ${o.time} WIB\nStatus: ${STATUS[o.status]}\nTotal: ${money(total(o))}\nDP: ${money(Math.ceil(total(o)*o.dpPercent/100))}\nSisa tagihan: ${money(balance(o))}\n\n[DEMO — jangan melakukan pembayaran nyata]`;openModal('Pesan siap dibagikan',`<p class="small muted">Tinjau dan salin teks. Prototipe tidak mengirim pesan secara otomatis.</p><label for="share-text">Ringkasan pesanan</label><textarea id="share-text" rows="12">${esc(msg)}</textarea><div class="modal-actions">${btn('Kembali','detail','secondary',id)}${btn(icon('copy')+'Salin teks','copy-message')}</div>`,true)}
function renewDialog(){if(!state.subscription.invoice){state.subscription.invoice={id:'INV-DEMO-'+Date.now().toString().slice(-6),status:'pending',amount:30000};persist()}const v=state.subscription.invoice;openModal('Tagihan langganan',`<span class="demo-pill">Simulasi pembayaran</span><h2 style="margin-top:18px">${v.id}</h2><div class="summary-line total"><span>Satu bulan</span><span>Rp30.000</span></div><p class="muted small" style="margin-top:15px">Pada versi produksi, admin memeriksa transfer sebelum mengaktifkan langganan. Tidak ada rekening pembayaran nyata pada demo.</p><div class="modal-actions">${btn('Tutup','close','secondary')}${btn('Simulasikan verifikasi admin','verify-invoice')}</div>`,true)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Berhasil disalin.')}catch{openModal('Salin secara manual',`<textarea rows="7" readonly>${esc(text)}</textarea><div class="modal-actions">${btn('Tutup','close')}</div>`,true)}}
function exportOrders(){const rows=filteredOrders(),data=[['Nomor','Pelanggan','Tanggal','Jam WIB','Status','Total','Dibayar bersih','Sisa','Penyerahan'],...rows.map(o=>[o.id,o.name,o.date,o.time,STATUS[o.status],total(o),paid(o),o.status==='cancelled'?'Tidak ditagih otomatis':balance(o),o.method])];const blob=new Blob(['\ufeff'+data.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pesankue-pesanan-'+today+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast(`${rows.length} pesanan diekspor.`)}
function refreshCheckout(){const form=$('#checkout-form'),saved=form?[...new FormData(form)]:[];render();const next=$('#checkout-form');if(next){for(const [k,v]of saved){const el=next.elements.namedItem(k);if(el){if(el.type==='checkbox')el.checked=true;else el.value=v}}syncFulfillment()}}
function syncFulfillment(){const select=$('#fulfillment'),box=$('#delivery-address-field'),input=$('#delivery-address');if(!select||!box)return;const delivery=select.value==='Dikirim';box.classList.toggle('hidden',!delivery);input.required=delivery;const shipping=$('#manual-shipping');if(shipping){shipping.readOnly=!delivery;if(!delivery)shipping.value='0'}}
function goto(hash){closeModal();location.hash=hash}
async function action(target){const a=target.dataset.action,id=target.dataset.id;switch(a){case'close':closeModal();break;case'detail':showDetail(id);break;case'new-order':newOrderDialog();syncFulfillment();break;case'edit-order':newOrderDialog(id);syncFulfillment();break;case'new-product':productDialog();break;case'edit-product':productDialog(id);break;case'toggle-product':{const p=state.products.find(p=>p.id===id);p.active=!p.active;persist();render();toast(p.active?'Produk diaktifkan.':'Produk dinonaktifkan. Riwayat pesanan tetap ada.');break}case'filter-pending':filters={search:'',status:'pending',payment:'all'};location.hash='pesanan';break;case'reset-filter':filters={search:'',status:'all',payment:'all'};render();break;case'export':exportOrders();break;case'calendar-date':calendarDate=id;calendarMonth=id.slice(0,7);if(route==='kalender')render();else location.hash='kalender';break;case'calendar-today':calendarDate=today;calendarMonth=today.slice(0,7);render();break;case'month-prev':case'month-next':{const d=new Date(calendarMonth+'-15T12:00:00+07:00');d.setMonth(d.getMonth()+(a==='month-prev'?-1:1));calendarMonth=dateISO(d).slice(0,7);render();break}case'add-cart':{if(isExpired())return toast('Toko sedang menutup penerimaan pesanan.');const p=state.products.find(p=>p.id===id&&p.active);if(!p)return;const v=p.variants[Number($('#variant-'+id).value)];const x=cart.find(x=>x.pid===id&&x.variant===v.name);if(x){if(x.qty>=999)return toast('Maksimal 999 per produk.');x.qty++}else cart.push({pid:id,name:p.name,variant:v.name,price:v.price,qty:1,note:''});render();toast('Produk ditambahkan ke keranjang.');break}case'checkout':location.hash='checkout';break;case'cart-plus':if(cart[Number(id)].qty<999)cart[Number(id)].qty++;refreshCheckout();break;case'cart-minus':if(--cart[Number(id)].qty<1)cart.splice(Number(id),1);refreshCheckout();break;case'draft-add':{const p=state.products.find(p=>p.active);if(!p)return toast('Tambahkan produk aktif terlebih dahulu.');const v=p.variants[0];draftItems.push({pid:p.id,name:p.name,variant:v.name,price:v.price,qty:1,note:''});$('#draft-items').innerHTML=draftRows();break}case'draft-remove':draftItems.splice(Number(id),1);$('#draft-items').innerHTML=draftRows();break;case'variant-add':{const n=$$('.variant-row').length;if(n>=10)return toast('Maksimal 10 variasi.');$('#variant-fields').insertAdjacentHTML('beforeend',variantRow({name:'',price:''},n));break}case'transition':transitionDialog(id,target.dataset.next);break;case'apply-transition':{const o=state.orders.find(o=>o.id===id),next=target.dataset.next;if(!o||!canTransition(o,next))return toast('Perubahan status tidak tersedia.');o.status=next;addEvent(o,'Status berubah menjadi '+STATUS[next]);persist();render();showDetail(id);toast('Status pesanan diperbarui.');break}case'payment':paymentDialog(id);break;case'refund':paymentDialog(id,true);break;case'cancel':cancelDialog(id);break;case'reject':cancelDialog(id,true);break;case'track':{const o=state.orders.find(o=>o.id===id);goto('status/'+o.token);break}case'copy-track':{const o=state.orders.find(o=>o.id===id);await copy(location.href.split('#')[0]+'#status/'+o.token);break}case'share':shareDialog(id);break;case'copy-message':await copy($('#share-text').value);break;case'expire':state.subscription.status='expired';persist();render();toast('Demo masa aktif habis diaktifkan.');break;case'activate':state.subscription.status='active';state.subscription.end=addDay(30);persist();render();toast('Demo toko aktif kembali.');break;case'renew':renewDialog();break;case'verify-invoice':{if(!state.subscription.invoice||state.subscription.invoice.status==='paid')return;state.subscription.invoice.status='paid';const base=isExpired()?today:state.subscription.end;const d=new Date(base+'T12:00:00+07:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);const max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,max));state.subscription.end=dateISO(d);state.subscription.status='active';state.subscription.invoice=null;persist();closeModal();render();toast('Simulasi verifikasi selesai. Masa aktif bertambah satu bulan.');break}case'setup-back':onboardingStep=Math.max(1,onboardingStep-1);render();break;case'forgot':openModal('Pemulihan password',`<p class="muted small">Pada versi produksi, tautan pemulihan dikirim lewat email. Demo ini tidak mengirim email.</p><form id="forgot-form">${field('Email','forgot-email','','email','required')}<div class="modal-actions"><button class="btn">Simulasikan permintaan</button></div></form>`,true);break;case'demo-toast':toast('Contoh respons komponen.');break;case'reset-demo':openModal('Reset data contoh',`<p>Semua perubahan lokal, produk dan pesanan demo akan diganti dengan data awal.</p><div class="modal-actions">${btn('Batal','close','secondary')}${btn('Ya, reset demo','confirm-reset','danger')}</div>`,true);break;case'confirm-reset':state=seed();cart=[];filters={search:'',status:'all',payment:'all'};persist();closeModal();render();toast('Data contoh dikembalikan.');break;}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target){e.preventDefault();Promise.resolve(action(target)).catch(err=>toast(err.message||'Tindakan belum berhasil. Coba lagi.'))}});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-money]')){const cleaned=el.value.replace(/[^0-9]/g,'');el.value=cleaned?Number(cleaned).toLocaleString('id-ID'):''}if(el.id==='order-search'){filters.search=el.value;$('#orders-list').innerHTML=orderRows(filteredOrders());$('#order-count').textContent=filteredOrders().length+' pesanan'}if(el.id==='product-search'){productSearch=el.value;$('#product-list').innerHTML=productCards()}if(el.closest('#settings-form'))$('#settings-save').disabled=false;if(el.dataset.itemQty!==undefined)draftItems[Number(el.dataset.itemQty)].qty=Number(el.value);if(el.dataset.itemNote!==undefined)draftItems[Number(el.dataset.itemNote)].note=el.value;if(['confirm-shipping','confirm-dp'].includes(el.id))updateConfirmTotals()});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='order-status'){filters.status=el.value;$('#orders-list').innerHTML=orderRows(filteredOrders());$('#order-count').textContent=filteredOrders().length+' pesanan'}if(el.id==='order-payment'){filters.payment=el.value;$('#orders-list').innerHTML=orderRows(filteredOrders());$('#order-count').textContent=filteredOrders().length+' pesanan'}if(el.id==='fulfillment')syncFulfillment();if(el.closest('#settings-form'))$('#settings-save').disabled=false;if(el.dataset.itemSelect!==undefined){const [pid,idx]=el.value.split(':'),p=state.products.find(p=>p.id===pid);if(!p)return;const v=p.variants[Number(idx)],i=Number(el.dataset.itemSelect);draftItems[i]={...draftItems[i],pid,name:p.name,variant:v.name,price:v.price}}if(el.id==='product-image'){const file=el.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){$('#product-error').textContent='Pilih JPEG, PNG, atau WebP maksimal 5 MB.';el.value='';return}const reader=new FileReader();$('#product-save').disabled=true;reader.onload=()=>{productImage=reader.result;$('#product-save').disabled=false;$('#product-error').textContent='';toast('Foto siap disimpan bersama produk.')};reader.onerror=()=>{$('#product-save').disabled=false;$('#product-error').textContent='Foto tidak dapat dibaca.'};reader.readAsDataURL(file)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);try{switch(f.id){case'checkout-form':{const customer=readCustomer(f),items=cart.map(x=>({...x,note:String(fd.get('customer-note')||'')}));if(!fd.get('consent'))throw new Error('Centang persetujuan pesanan.');const o=makeOrder(customer,items,'Link toko');cart=[];location.hash='status/'+o.token;toast('Pesanan terkirim. Tunggu konfirmasi toko.');break}case'manual-form':{const customer=readCustomer(f),shipping=parseAmount(fd.get('manual-shipping'));if(shipping>100000000)throw new Error('Ongkir maksimal Rp100.000.000.');if(!draftItems.length)throw new Error('Tambahkan minimal satu produk.');if(draftItems.some(x=>!Number.isInteger(x.qty)||x.qty<1||x.qty>999))throw new Error('Jumlah produk harus 1 sampai 999.');let o;if(editOrderId){o=state.orders.find(x=>x.id===editOrderId);Object.assign(o,customer,{items:structuredClone(draftItems),shipping:customer.method==='Dikirim'?shipping:0});addEvent(o,'Detail pesanan diperbarui setelah kesepakatan pelanggan');persist()}else{o=makeOrder(customer,draftItems,'Manual',!!fd.get('confirmed'),shipping)}closeModal();render();showDetail(o.id);toast(editOrderId?'Pesanan diperbarui.':'Pesanan manual dibuat.');break}case'confirm-form':{const o=state.orders.find(o=>o.id===currentOrder);if(!o||!canTransition(o,'confirmed'))throw new Error('Pesanan sudah berubah. Muat ulang detailnya.');const shipping=parseAmount(fd.get('confirm-shipping')),dp=Number(fd.get('confirm-dp'));if(shipping>100000000||dp<0||dp>100||!Number.isInteger(dp))throw new Error('Periksa ongkir dan persentase DP.');o.shipping=o.method==='Dikirim'?shipping:0;o.dpPercent=dp;o.status='confirmed';o.bank={bank:state.shop.bank,account:state.shop.account,holder:state.shop.holder};addEvent(o,'Pesanan dikonfirmasi · total '+money(total(o)));persist();render();showDetail(o.id);toast('Pesanan dikonfirmasi. Tagihan siap dibagikan.');break}case'payment-form':{const o=state.orders.find(o=>o.id===currentOrder),amount=parseAmount(fd.get('payment-amount')),type=f.dataset.type;validatePayment(o,amount,type);const date=String(fd.get('payment-date'));if(!date||date>today)throw new Error('Tanggal pembayaran tidak boleh di masa depan.');o.payments.push({id:uid(),amount,type,date,method:String(fd.get('payment-method')),note:String(fd.get('payment-note')||'').trim()});addEvent(o,(type==='refund'?'Pengembalian':'Pembayaran')+' dicatat '+money(amount));persist();render();showDetail(o.id);toast(type==='refund'?'Pengembalian dicatat.':'Pembayaran berhasil dicatat.');break}case'cancel-form':{const o=state.orders.find(o=>o.id===currentOrder),next=f.dataset.status;if(!canTransition(o,next))throw new Error('Status pesanan tidak bisa diubah.');o.status=next;o.reason=String(fd.get('reason')).trim();addEvent(o,STATUS[next]+': '+o.reason);persist();render();showDetail(o.id);toast('Pesanan '+STATUS[next].toLowerCase()+'.');break}case'product-form':{const names=$$('.variant-name',f).map(x=>x.value.trim()),prices=$$('.variant-price',f).map(x=>parseAmount(x.value));if(names.some(n=>!n)||new Set(names.map(x=>x.toLowerCase())).size!==names.length)throw new Error('Nama variasi harus diisi dan tidak boleh sama.');if(prices.some(p=>p<=0||p>100000000))throw new Error('Harga harus Rp1 sampai Rp100.000.000.');const name=String(fd.get('product-name')).trim();if(name.length<2)throw new Error('Nama produk minimal 2 karakter.');const p={id:productEditing||uid(),name,description:String(fd.get('product-description')||''),photo:String(fd.get('product-photo')),image:productImage,active:productEditing?state.products.find(x=>x.id===productEditing).active:true,variants:names.map((name,i)=>({name,price:prices[i]}))};const i=state.products.findIndex(x=>x.id===productEditing);if(i>=0)state.products[i]=p;else state.products.push(p);persist();closeModal();render();toast('Produk berhasil disimpan.');break}case'settings-form':{const wa=normalizeWA(fd.get('shop-wa'));if(!wa)throw new Error('Periksa nomor WhatsApp toko.');if(!fd.get('pickup')&&!fd.get('delivery'))throw new Error('Aktifkan minimal satu metode penyerahan.');const dp=Number(fd.get('dp'));if(!Number.isInteger(dp)||dp<0||dp>100)throw new Error('DP harus 0 sampai 100 persen.');state.shop={...state.shop,name:String(fd.get('shop-name')).trim(),owner:String(fd.get('owner')).trim(),wa,address:String(fd.get('address')).trim(),bank:String(fd.get('bank')).trim(),account:String(fd.get('account')).trim(),holder:String(fd.get('holder')).trim(),dp,pickup:!!fd.get('pickup'),delivery:!!fd.get('delivery')};persist();render();toast('Pengaturan toko disimpan.');break}case'login-form':goto('ringkasan');toast('Masuk ke ruang kerja demo. Tidak ada autentikasi nyata.');break;case'register-form':if(fd.get('auth-password')!==fd.get('auth-confirm'))throw new Error('Konfirmasi password belum sama.');setupDraft.owner=String(fd.get('auth-name')).trim();onboardingStep=1;goto('onboarding');break;case'forgot-form':closeModal();toast('Simulasi permintaan selesai. Tidak ada email yang dikirim.');break;case'onboarding-form':if(onboardingStep===1){const wa=normalizeWA(fd.get('setup-wa'));if(!wa)throw new Error('Periksa nomor WhatsApp.');Object.assign(setupDraft,{name:String(fd.get('setup-name')).trim(),owner:String(fd.get('setup-owner')).trim(),wa,address:String(fd.get('setup-address')).trim()});onboardingStep=2;render()}else if(onboardingStep===2){Object.assign(setupDraft,{bank:String(fd.get('setup-bank')).trim(),account:String(fd.get('setup-account')).trim(),holder:String(fd.get('setup-holder')).trim(),dp:Number(fd.get('setup-dp'))});onboardingStep=3;render()}else{state.shop={...state.shop,...setupDraft};if(!state.setupComplete){state.subscription={status:'trial',end:addDay(7),invoice:null};state.setupComplete=true}persist();setupDraft={};onboardingStep=1;goto('ringkasan');toast('Toko demo siap. Produk contoh dapat diubah.')}break;}}catch(err){const map={'checkout-form':'checkout-error','manual-form':'manual-error','confirm-form':'confirm-error','payment-form':'payment-error','product-form':'product-error','settings-form':'settings-error','login-form':'auth-error','register-form':'auth-error','onboarding-form':'setup-error'};const el=$('#'+map[f.id]);if(el){el.textContent=err.message;el.scrollIntoView({block:'nearest'})}else toast(err.message)}});
