if(registry?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_demo_orders',title:'Lihat pesanan demo',description:'Read local prototype orders. Data is fictitious and exists only in this browser.',inputSchema:{type:'object',properties:{status:{type:'string',enum:Object.keys(STATUS)}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='status')||(input.status&&!STATUS[input.status]))throw new Error('Status tidak valid');return {orders:state.orders.filter(o=>!input.status||o.status===input.status).map(o=>({id:o.id,name:o.name,status:o.status,date:o.date,total:total(o),balance:balance(o)}))}}},{name:'open_demo_order',title:'Buka detail pesanan demo',description:'Open an existing local demo order detail. Does not change the order.',inputSchema:{type:'object',properties:{orderId:{type:'string'}},required:['orderId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.orderId!=='string'||Object.keys(input).some(k=>k!=='orderId')||!state.orders.some(o=>o.id===input.orderId))throw new Error('Pesanan tidak ditemukan');showDetail(input.orderId);return {opened:true,orderId:input.orderId}}}];for(const tool of tools){try{Promise.resolve(registry.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
